UPDATE public.psa_proposal_blocks SET content_rich='{"html":"<p>A nossa proposta refere-se à elaboração dos estudos, projeto de arquitetura e assistência à execução da obra de remodelação de um espaço comercial em Lisboa. Ainda não existe programa específico para o espaço, sendo que será apresentado pelo cliente e debatido na fase de projeto. A intervenção consiste na ampliação da Clínica Dentária existente na loja do piso térreo, utilizando o espaço comercial contíguo do mesmo edifício, podendo ter de se justificar a intervenção na fachada principal do edifício. Localização: Avenida Marquês de Tomar 5, Lisboa. Área de intervenção prevista: 270 m².</p>","text":"A nossa proposta refere-se à elaboração dos estudos, projeto de arquitetura e assistência à execução da obra de remodelação de um espaço comercial em Lisboa. Ainda não existe programa específico para o espaço, sendo que será apresentado pelo cliente e debatido na fase de projeto. A intervenção consiste na ampliação da Clínica Dentária existente na loja do piso térreo, utilizando o espaço comercial contíguo do mesmo edifício, podendo ter de se justificar a intervenção na fachada principal do edifício. Localização: Avenida Marquês de Tomar 5, Lisboa. Área de intervenção prevista: 270 m².","replace_project_description":true}'::jsonb, title='Âmbito e Descrição do Projeto', sort_order=40 WHERE id='f2ac28e5-af58-476c-b397-a86992502ab0' AND proposal_id='20c4c8b3-c84b-4297-aabb-bc5d17414d84' AND (content_rich IS DISTINCT FROM '{"html":"<p>A nossa proposta refere-se à elaboração dos estudos, projeto de arquitetura e assistência à execução da obra de remodelação de um espaço comercial em Lisboa. Ainda não existe programa específico para o espaço, sendo que será apresentado pelo cliente e debatido na fase de projeto. A intervenção consiste na ampliação da Clínica Dentária existente na loja do piso térreo, utilizando o espaço comercial contíguo do mesmo edifício, podendo ter de se justificar a intervenção na fachada principal do edifício. Localização: Avenida Marquês de Tomar 5, Lisboa. Área de intervenção prevista: 270 m².</p>","text":"A nossa proposta refere-se à elaboração dos estudos, projeto de arquitetura e assistência à execução da obra de remodelação de um espaço comercial em Lisboa. Ainda não existe programa específico para o espaço, sendo que será apresentado pelo cliente e debatido na fase de projeto. A intervenção consiste na ampliação da Clínica Dentária existente na loja do piso térreo, utilizando o espaço comercial contíguo do mesmo edifício, podendo ter de se justificar a intervenção na fachada principal do edifício. Localização: Avenida Marquês de Tomar 5, Lisboa. Área de intervenção prevista: 270 m².","replace_project_description":true}'::jsonb OR title IS DISTINCT FROM 'Âmbito e Descrição do Projeto' OR sort_order IS DISTINCT FROM 40);
UPDATE public.psa_proposal_blocks SET content_rich='{"html":"<p>Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com as intenções do cliente e com as condicionantes do Projeto. Faremos também a coordenação do projeto de Arquitetura com os diferentes projetos de Especialidades.</p><p>Iremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra.</p>","text":"Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com as intenções do cliente e com as condicionantes do Projeto. Faremos também a coordenação do projeto de Arquitetura com os diferentes projetos de Especialidades.\n\nIremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra.","deliverables":"Plantas gerais – escala 1:50\nPlantas de acabamentos – escala 1:50\nPlantas de tetos, indicando materiais e pontos de iluminação – escala 1:50\nCortes – escala 1:50\nAlçados – escala 1:50\nDetalhes de zonas específicas (instalações sanitárias, copas e outras áreas conforme necessário) – escala 1:20\nMapas de vãos e mobiliário – à escala apropriada\nDescrição de acabamentos e equipamentos\nMapa de Quantidades, Medições e Estimativa Orçamental\nVerificação e coordenação dos elementos dos projetos de Especialidades","duration_label":"5 semanas","objective_html":"<p>Especificar de forma completa todos os materiais, soluções e trabalhos necessários para a execução da obra, devidamente coordenados com os projetos de Especialidades.</p>","objective_text":"Especificar de forma completa todos os materiais, soluções e trabalhos necessários para a execução da obra, devidamente coordenados com os projetos de Especialidades.","key_activities_html":"<ul><li><p>Desenvolvimento das soluções estéticas e construtivas do projeto de arquitetura;</p></li><li><p>Elaboração de desenhos e elementos escritos de especificação de materiais e trabalhos;</p></li><li><p>Coordenação, verificação e compatibilização com os elementos dos projetos de Especialidades.</p></li></ul><p></p>","key_activities_text":"\n\n\n\nDesenvolvimento das soluções estéticas e construtivas do projeto de arquitetura;\n\n\n\nElaboração de desenhos e elementos escritos de especificação de materiais e trabalhos;\n\n\n\nCoordenação, verificação e compatibilização com os elementos dos projetos de Especialidades.\n\n","stage_approval_html":"<p>A fase considera-se concluída com a entrega dos elementos do projeto de execução e a sua aceitação pelo cliente.</p>","stage_approval_text":"A fase considera-se concluída com a entrega dos elementos do projeto de execução e a sua aceitação pelo cliente."}'::jsonb, title='Fase', sort_order=80 WHERE id='86ad53d1-edff-46ef-a5ae-193365773d87' AND proposal_id='20c4c8b3-c84b-4297-aabb-bc5d17414d84' AND (content_rich IS DISTINCT FROM '{"html":"<p>Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com as intenções do cliente e com as condicionantes do Projeto. Faremos também a coordenação do projeto de Arquitetura com os diferentes projetos de Especialidades.</p><p>Iremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra.</p>","text":"Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com as intenções do cliente e com as condicionantes do Projeto. Faremos também a coordenação do projeto de Arquitetura com os diferentes projetos de Especialidades.\n\nIremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra.","deliverables":"Plantas gerais – escala 1:50\nPlantas de acabamentos – escala 1:50\nPlantas de tetos, indicando materiais e pontos de iluminação – escala 1:50\nCortes – escala 1:50\nAlçados – escala 1:50\nDetalhes de zonas específicas (instalações sanitárias, copas e outras áreas conforme necessário) – escala 1:20\nMapas de vãos e mobiliário – à escala apropriada\nDescrição de acabamentos e equipamentos\nMapa de Quantidades, Medições e Estimativa Orçamental\nVerificação e coordenação dos elementos dos projetos de Especialidades","duration_label":"5 semanas","objective_html":"<p>Especificar de forma completa todos os materiais, soluções e trabalhos necessários para a execução da obra, devidamente coordenados com os projetos de Especialidades.</p>","objective_text":"Especificar de forma completa todos os materiais, soluções e trabalhos necessários para a execução da obra, devidamente coordenados com os projetos de Especialidades.","key_activities_html":"<ul><li><p>Desenvolvimento das soluções estéticas e construtivas do projeto de arquitetura;</p></li><li><p>Elaboração de desenhos e elementos escritos de especificação de materiais e trabalhos;</p></li><li><p>Coordenação, verificação e compatibilização com os elementos dos projetos de Especialidades.</p></li></ul><p></p>","key_activities_text":"\n\n\n\nDesenvolvimento das soluções estéticas e construtivas do projeto de arquitetura;\n\n\n\nElaboração de desenhos e elementos escritos de especificação de materiais e trabalhos;\n\n\n\nCoordenação, verificação e compatibilização com os elementos dos projetos de Especialidades.\n\n","stage_approval_html":"<p>A fase considera-se concluída com a entrega dos elementos do projeto de execução e a sua aceitação pelo cliente.</p>","stage_approval_text":"A fase considera-se concluída com a entrega dos elementos do projeto de execução e a sua aceitação pelo cliente."}'::jsonb OR title IS DISTINCT FROM 'Fase' OR sort_order IS DISTINCT FROM 80);
UPDATE public.psa_proposal_blocks SET content_rich='{"html":"<p>Na fase de construção, faremos o acompanhamento da obra através de reuniões no local com o Empreiteiro Geral, a Fiscalização e os restantes técnicos responsáveis pelos projetos de Especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura e o esclarecimento de eventuais dúvidas. Nesta fase serão fornecidos desenhos ou outros elementos adicionais que esclareçam dúvidas ou omissões do projeto de execução.</p><p>O valor mensal inclui 2 visitas mensais à obra, as respetivas deslocações e o apoio de atelier necessário aos esclarecimentos. Será cobrado durante todo o período de construção (com exceção da fase de demolições) até à conclusão da obra.</p><p>A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra.</p>","text":"Na fase de construção, faremos o acompanhamento da obra através de reuniões no local com o Empreiteiro Geral, a Fiscalização e os restantes técnicos responsáveis pelos projetos de Especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura e o esclarecimento de eventuais dúvidas. Nesta fase serão fornecidos desenhos ou outros elementos adicionais que esclareçam dúvidas ou omissões do projeto de execução.\n\nO valor mensal inclui 2 visitas mensais à obra, as respetivas deslocações e o apoio de atelier necessário aos esclarecimentos. Será cobrado durante todo o período de construção (com exceção da fase de demolições) até à conclusão da obra.\n\nA Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra.","deliverables":"Desenhos e elementos adicionais de esclarecimento de dúvidas ou omissões do projeto de execução\nParticipação em reuniões de obra","duration_label":"4 meses","objective_html":"<p>Garantir a correta interpretação do projeto de Arquitetura em obra e o esclarecimento atempado de dúvidas e omissões.</p>","objective_text":"Garantir a correta interpretação do projeto de Arquitetura em obra e o esclarecimento atempado de dúvidas e omissões.","key_activities_html":"<ul><li><p>Visitas à obra com reunião de obra (2 visitas mensais);</p></li><li><p>Trabalho de atelier de apoio ao esclarecimento de dúvidas e resolução de problemas.</p></li></ul><p></p>","key_activities_text":"\n\n\n\nVisitas à obra com reunião de obra (2 visitas mensais);\n\n\n\nTrabalho de atelier de apoio ao esclarecimento de dúvidas e resolução de problemas.\n\n","stage_approval_html":"<p>Fase faturada mensalmente durante o período de construção, até à conclusão da obra.</p>","stage_approval_text":"Fase faturada mensalmente durante o período de construção, até à conclusão da obra."}'::jsonb, title='Fase', sort_order=85 WHERE id='2474290b-2c76-4e3e-add6-fde43659aafb' AND proposal_id='20c4c8b3-c84b-4297-aabb-bc5d17414d84' AND (content_rich IS DISTINCT FROM '{"html":"<p>Na fase de construção, faremos o acompanhamento da obra através de reuniões no local com o Empreiteiro Geral, a Fiscalização e os restantes técnicos responsáveis pelos projetos de Especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura e o esclarecimento de eventuais dúvidas. Nesta fase serão fornecidos desenhos ou outros elementos adicionais que esclareçam dúvidas ou omissões do projeto de execução.</p><p>O valor mensal inclui 2 visitas mensais à obra, as respetivas deslocações e o apoio de atelier necessário aos esclarecimentos. Será cobrado durante todo o período de construção (com exceção da fase de demolições) até à conclusão da obra.</p><p>A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra.</p>","text":"Na fase de construção, faremos o acompanhamento da obra através de reuniões no local com o Empreiteiro Geral, a Fiscalização e os restantes técnicos responsáveis pelos projetos de Especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura e o esclarecimento de eventuais dúvidas. Nesta fase serão fornecidos desenhos ou outros elementos adicionais que esclareçam dúvidas ou omissões do projeto de execução.\n\nO valor mensal inclui 2 visitas mensais à obra, as respetivas deslocações e o apoio de atelier necessário aos esclarecimentos. Será cobrado durante todo o período de construção (com exceção da fase de demolições) até à conclusão da obra.\n\nA Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra.","deliverables":"Desenhos e elementos adicionais de esclarecimento de dúvidas ou omissões do projeto de execução\nParticipação em reuniões de obra","duration_label":"4 meses","objective_html":"<p>Garantir a correta interpretação do projeto de Arquitetura em obra e o esclarecimento atempado de dúvidas e omissões.</p>","objective_text":"Garantir a correta interpretação do projeto de Arquitetura em obra e o esclarecimento atempado de dúvidas e omissões.","key_activities_html":"<ul><li><p>Visitas à obra com reunião de obra (2 visitas mensais);</p></li><li><p>Trabalho de atelier de apoio ao esclarecimento de dúvidas e resolução de problemas.</p></li></ul><p></p>","key_activities_text":"\n\n\n\nVisitas à obra com reunião de obra (2 visitas mensais);\n\n\n\nTrabalho de atelier de apoio ao esclarecimento de dúvidas e resolução de problemas.\n\n","stage_approval_html":"<p>Fase faturada mensalmente durante o período de construção, até à conclusão da obra.</p>","stage_approval_text":"Fase faturada mensalmente durante o período de construção, até à conclusão da obra."}'::jsonb OR title IS DISTINCT FROM 'Fase' OR sort_order IS DISTINCT FROM 85);
