UPDATE public.psa_proposal_blocks SET content_rich='{"html":"<p>Se no decorrer da prestação de serviços surgirem despesas ou trabalhos não contemplados na descrição constante nas fases de projeto aqui descritas, iremos informar e propor uma alteração aos honorários ou honorários adicionais, em regime geral ou em regime horário. Regime geral: honorários calculados em função de uma estimativa do tempo e dos recursos a utilizar, apresentados se o cliente solicitar alterações na dimensão ou complexidade do projeto, outros serviços para além dos definidos nesta proposta, ou se for acordada entre ambas as partes uma alteração da proposta. Regime horário: honorários cobrados à hora, aplicáveis quando for necessário mais tempo de projeto para atingir as expectativas e requisitos do cliente além do tempo estimado, a quaisquer trabalhos relacionados com fases anteriores já aprovadas, e a trabalhos solicitados tardiamente que prolonguem a fase em curso ou afetem o planeamento geral.</p><table><tbody><tr><td>Arquiteto Gestor de Projeto</td><td>90,00 €/h</td></tr><tr><td>Arquiteto Coordenador</td><td>75,00 €/h</td></tr><tr><td>Arquiteto</td><td>60,00 €/h</td></tr><tr><td>Arquiteto Júnior</td><td>45,00 €/h</td></tr><tr><td>3D Visualizer</td><td>60,00 €/h</td></tr><tr><td>Designer de Interiores</td><td>50,00 €/h</td></tr><tr><td>Designer Gráfico</td><td>45,00 €/h</td></tr></tbody></table>","text":"Se no decorrer da prestação de serviços surgirem despesas ou trabalhos não contemplados na descrição constante nas fases de projeto aqui descritas, iremos informar e propor uma alteração aos honorários ou honorários adicionais, em regime geral ou em regime horário. Regime geral: honorários calculados em função de uma estimativa do tempo e dos recursos a utilizar, apresentados se o cliente solicitar alterações na dimensão ou complexidade do projeto, outros serviços para além dos definidos nesta proposta, ou se for acordada entre ambas as partes uma alteração da proposta. Regime horário: honorários cobrados à hora, aplicáveis quando for necessário mais tempo de projeto para atingir as expectativas e requisitos do cliente além do tempo estimado, a quaisquer trabalhos relacionados com fases anteriores já aprovadas, e a trabalhos solicitados tardiamente que prolonguem a fase em curso ou afetem o planeamento geral."}'::jsonb, title='Serviços Adicionais', sort_order=170 WHERE id='dbb3a5b9-e9bd-4d9c-99d9-940aba312b1c' AND proposal_id='20c4c8b3-c84b-4297-aabb-bc5d17414d84' AND (content_rich IS DISTINCT FROM '{"html":"<p>Se no decorrer da prestação de serviços surgirem despesas ou trabalhos não contemplados na descrição constante nas fases de projeto aqui descritas, iremos informar e propor uma alteração aos honorários ou honorários adicionais, em regime geral ou em regime horário. Regime geral: honorários calculados em função de uma estimativa do tempo e dos recursos a utilizar, apresentados se o cliente solicitar alterações na dimensão ou complexidade do projeto, outros serviços para além dos definidos nesta proposta, ou se for acordada entre ambas as partes uma alteração da proposta. Regime horário: honorários cobrados à hora, aplicáveis quando for necessário mais tempo de projeto para atingir as expectativas e requisitos do cliente além do tempo estimado, a quaisquer trabalhos relacionados com fases anteriores já aprovadas, e a trabalhos solicitados tardiamente que prolonguem a fase em curso ou afetem o planeamento geral.</p><table><tbody><tr><td>Arquiteto Gestor de Projeto</td><td>90,00 €/h</td></tr><tr><td>Arquiteto Coordenador</td><td>75,00 €/h</td></tr><tr><td>Arquiteto</td><td>60,00 €/h</td></tr><tr><td>Arquiteto Júnior</td><td>45,00 €/h</td></tr><tr><td>3D Visualizer</td><td>60,00 €/h</td></tr><tr><td>Designer de Interiores</td><td>50,00 €/h</td></tr><tr><td>Designer Gráfico</td><td>45,00 €/h</td></tr></tbody></table>","text":"Se no decorrer da prestação de serviços surgirem despesas ou trabalhos não contemplados na descrição constante nas fases de projeto aqui descritas, iremos informar e propor uma alteração aos honorários ou honorários adicionais, em regime geral ou em regime horário. Regime geral: honorários calculados em função de uma estimativa do tempo e dos recursos a utilizar, apresentados se o cliente solicitar alterações na dimensão ou complexidade do projeto, outros serviços para além dos definidos nesta proposta, ou se for acordada entre ambas as partes uma alteração da proposta. Regime horário: honorários cobrados à hora, aplicáveis quando for necessário mais tempo de projeto para atingir as expectativas e requisitos do cliente além do tempo estimado, a quaisquer trabalhos relacionados com fases anteriores já aprovadas, e a trabalhos solicitados tardiamente que prolonguem a fase em curso ou afetem o planeamento geral."}'::jsonb OR title IS DISTINCT FROM 'Serviços Adicionais' OR sort_order IS DISTINCT FROM 170);
UPDATE public.psa_proposal_blocks SET content_rich='{"html":"<p>Cessação do contrato: O cliente poderá cessar o contrato em qualquer fase de projeto com a antecedência devida de 20 dias úteis, ficando responsável por pagar a totalidade da fase que estiver a decorrer. Suspensão do contrato: Na eventualidade de ser necessário suspender o contrato por tempo indeterminado, e por razões fora do controlo da equipa projetista, será cobrado um valor mensal de standby equivalente a 50% do valor das mensalidades do contrato.</p>","text":"Cessação do contrato: O cliente poderá cessar o contrato em qualquer fase de projeto com a antecedência devida de 20 dias úteis, ficando responsável por pagar a totalidade da fase que estiver a decorrer. Suspensão do contrato: Na eventualidade de ser necessário suspender o contrato por tempo indeterminado, e por razões fora do controlo da equipa projetista, será cobrado um valor mensal de standby equivalente a 50% do valor das mensalidades do contrato."}'::jsonb, title='Suspensão ou Rescisão', sort_order=190 WHERE id='be4d9623-0c81-4a6a-88a9-46932f7d70fc' AND proposal_id='20c4c8b3-c84b-4297-aabb-bc5d17414d84' AND (content_rich IS DISTINCT FROM '{"html":"<p>Cessação do contrato: O cliente poderá cessar o contrato em qualquer fase de projeto com a antecedência devida de 20 dias úteis, ficando responsável por pagar a totalidade da fase que estiver a decorrer. Suspensão do contrato: Na eventualidade de ser necessário suspender o contrato por tempo indeterminado, e por razões fora do controlo da equipa projetista, será cobrado um valor mensal de standby equivalente a 50% do valor das mensalidades do contrato.</p>","text":"Cessação do contrato: O cliente poderá cessar o contrato em qualquer fase de projeto com a antecedência devida de 20 dias úteis, ficando responsável por pagar a totalidade da fase que estiver a decorrer. Suspensão do contrato: Na eventualidade de ser necessário suspender o contrato por tempo indeterminado, e por razões fora do controlo da equipa projetista, será cobrado um valor mensal de standby equivalente a 50% do valor das mensalidades do contrato."}'::jsonb OR title IS DISTINCT FROM 'Suspensão ou Rescisão' OR sort_order IS DISTINCT FROM 190);
UPDATE public.psa_proposal_blocks SET content_rich='{"html":"<ul><li><p>IVA à taxa legal em vigor</p></li><li><p>Despesas de deslocação como viagens, alojamento, refeições e despesas diversas associadas, fora do Concelho de Lisboa, que não estão contempladas no capítulo da Assistência Técnica</p></li><li><p>Todos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos, levantamentos arquitetónicos, estudos geotécnicos e geológicos, etc.</p></li><li><p>Projetos de Especialidades e de Paisagismo (a contratar diretamente pelo cliente; a nossa equipa assegura a coordenação com a Arquitetura)</p></li><li><p>Projeto de Licenciamento na Câmara Municipal (se vier a ser obrigatório, será objeto de proposta adicional)</p></li><li><p>Projeto de licenciamento específico na Entidade Reguladora da Saúde (ERS)</p></li><li><p>Taxas camarárias</p></li><li><p>Preparação e lançamento de concurso de empreitadas</p></li><li><p>Direção técnica da obra, administração da obra, coordenação e fiscalização da obra</p></li><li><p>Elaboração de desenhos de preparação de obra</p></li><li><p>Caderno de encargos e condições técnicas especiais</p></li><li><p>Maquetes profissionais</p></li><li><p>Imagens 3D para além das previstas na fase de Estudo Prévio</p></li><li><p>Processo de obtenção de licença de utilização (telas finais e outros documentos para a Câmara Municipal), na fase após a obra</p></li><li><p>Projetos especiais (cozinhas técnicas, piscinas e spa)</p></li><li><p>Pedidos ou negociações para a obtenção de financiamentos (privados ou corporate)</p></li><li><p>Certificação energética e acústica</p></li><li><p>Preparação de desenhos ou 3D para utilização de marketing</p></li><li><p>Projeto de mobiliário e decoração</p></li></ul>","text":"IVA à taxa legal em vigor\nDespesas de deslocação como viagens, alojamento, refeições e despesas diversas associadas, fora do Concelho de Lisboa, que não estão contempladas no capítulo da Assistência Técnica\nTodos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos, levantamentos arquitetónicos, estudos geotécnicos e geológicos, etc.\nProjetos de Especialidades e de Paisagismo (a contratar diretamente pelo cliente; a nossa equipa assegura a coordenação com a Arquitetura)\nProjeto de Licenciamento na Câmara Municipal (se vier a ser obrigatório, será objeto de proposta adicional)\nProjeto de licenciamento específico na Entidade Reguladora da Saúde (ERS)\nTaxas camarárias\nPreparação e lançamento de concurso de empreitadas\nDireção técnica da obra, administração da obra, coordenação e fiscalização da obra\nElaboração de desenhos de preparação de obra\nCaderno de encargos e condições técnicas especiais\nMaquetes profissionais\nImagens 3D para além das previstas na fase de Estudo Prévio\nProcesso de obtenção de licença de utilização (telas finais e outros documentos para a Câmara Municipal), na fase após a obra\nProjetos especiais (cozinhas técnicas, piscinas e spa)\nPedidos ou negociações para a obtenção de financiamentos (privados ou corporate)\nCertificação energética e acústica\nPreparação de desenhos ou 3D para utilização de marketing\nProjeto de mobiliário e decoração"}'::jsonb, title='Exclusões', sort_order=200 WHERE id='3c4826d9-b577-4f64-a9c5-65edab81b0f7' AND proposal_id='20c4c8b3-c84b-4297-aabb-bc5d17414d84' AND (content_rich IS DISTINCT FROM '{"html":"<ul><li><p>IVA à taxa legal em vigor</p></li><li><p>Despesas de deslocação como viagens, alojamento, refeições e despesas diversas associadas, fora do Concelho de Lisboa, que não estão contempladas no capítulo da Assistência Técnica</p></li><li><p>Todos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos, levantamentos arquitetónicos, estudos geotécnicos e geológicos, etc.</p></li><li><p>Projetos de Especialidades e de Paisagismo (a contratar diretamente pelo cliente; a nossa equipa assegura a coordenação com a Arquitetura)</p></li><li><p>Projeto de Licenciamento na Câmara Municipal (se vier a ser obrigatório, será objeto de proposta adicional)</p></li><li><p>Projeto de licenciamento específico na Entidade Reguladora da Saúde (ERS)</p></li><li><p>Taxas camarárias</p></li><li><p>Preparação e lançamento de concurso de empreitadas</p></li><li><p>Direção técnica da obra, administração da obra, coordenação e fiscalização da obra</p></li><li><p>Elaboração de desenhos de preparação de obra</p></li><li><p>Caderno de encargos e condições técnicas especiais</p></li><li><p>Maquetes profissionais</p></li><li><p>Imagens 3D para além das previstas na fase de Estudo Prévio</p></li><li><p>Processo de obtenção de licença de utilização (telas finais e outros documentos para a Câmara Municipal), na fase após a obra</p></li><li><p>Projetos especiais (cozinhas técnicas, piscinas e spa)</p></li><li><p>Pedidos ou negociações para a obtenção de financiamentos (privados ou corporate)</p></li><li><p>Certificação energética e acústica</p></li><li><p>Preparação de desenhos ou 3D para utilização de marketing</p></li><li><p>Projeto de mobiliário e decoração</p></li></ul>","text":"IVA à taxa legal em vigor\nDespesas de deslocação como viagens, alojamento, refeições e despesas diversas associadas, fora do Concelho de Lisboa, que não estão contempladas no capítulo da Assistência Técnica\nTodos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos, levantamentos arquitetónicos, estudos geotécnicos e geológicos, etc.\nProjetos de Especialidades e de Paisagismo (a contratar diretamente pelo cliente; a nossa equipa assegura a coordenação com a Arquitetura)\nProjeto de Licenciamento na Câmara Municipal (se vier a ser obrigatório, será objeto de proposta adicional)\nProjeto de licenciamento específico na Entidade Reguladora da Saúde (ERS)\nTaxas camarárias\nPreparação e lançamento de concurso de empreitadas\nDireção técnica da obra, administração da obra, coordenação e fiscalização da obra\nElaboração de desenhos de preparação de obra\nCaderno de encargos e condições técnicas especiais\nMaquetes profissionais\nImagens 3D para além das previstas na fase de Estudo Prévio\nProcesso de obtenção de licença de utilização (telas finais e outros documentos para a Câmara Municipal), na fase após a obra\nProjetos especiais (cozinhas técnicas, piscinas e spa)\nPedidos ou negociações para a obtenção de financiamentos (privados ou corporate)\nCertificação energética e acústica\nPreparação de desenhos ou 3D para utilização de marketing\nProjeto de mobiliário e decoração"}'::jsonb OR title IS DISTINCT FROM 'Exclusões' OR sort_order IS DISTINCT FROM 200);
